program.source:
Algoritmo Tip
  Definir bill Como Entero;
  Definir friends Como Entero;
  Leer bill;
  Leer friends;
  Si friends = 0 Entonces
    Escribir "Nobody is there to pay";
  Sino
    Escribir "Each one pays: ", techo((bill + bill div 10) / friends);
  FinSi
FinAlgoritmo

